from pathlib import Path
import sys
p=Path(__file__).parent;source=Path(sys.argv[1]).read_text()
source=source.replace('// query_line_optional(x): 空ならnullopt、それ以外はquery_lineと同じ。','// query_line_optional(x): 空ならnullopt、それ以外はquery_lineと同じ。\n// query_with_line(x): 1回の探索でResult{最適値,k,m}を返す。queryと同じ前提・O(log h)。\n// query_with_line_optional(x): 空ならnullopt、それ以外はquery_with_lineと同じ。')
source=source.replace('  static constexpr T inf = lc_inf<T>();','  static constexpr T inf = lc_inf<T>();\n  struct Result { T value, k, m; };')
needle='  std::optional<std::pair<T,T>> query_line_optional(T x) const {'
assert needle in source
pos=source.index(needle);end=source.index('\n  }',pos)+4
source=source[:end]+'''
#if defined(__GNUC__) || defined(__clang__)
  __attribute__((always_inline))
#endif
  Result query_with_line(T x) const {
    const auto line = selected(x);
    return {evaluate(line->k, line->m, x), line->k, line->m};
  }
#if defined(__GNUC__) || defined(__clang__)
  __attribute__((always_inline))
#endif
  std::optional<Result> query_with_line_optional(T x) const {
    check_x(x);
    if (empty()) return std::nullopt;
    const auto line = lower_bound(x);
    return Result{evaluate(line->k, line->m, x), line->k, line->m};
  }'''+source[end:]
Path(sys.argv[2]).write_text(source)

