from pathlib import Path
import random,subprocess,json,hashlib
p=Path(__file__).parent;rng=random.Random(915873);checks=0;records=[]
for case in range(48):
 n=rng.randrange(1,51);q=200;points=[(rng.randrange(-10**9,10**9+1),rng.randrange(-10**18,10**18+1))for _ in range(n)];lines=[f'{n} {q}']+[f'{a} {b}'for a,b in points];answers=[]
 for _ in range(q):
  if rng.randrange(3)==0:
   a=rng.randrange(-10**9,10**9+1);b=rng.randrange(-10**18,10**18+1);lines.append(f'0 {a} {b}');points.append((a,b))
  else:
   x=rng.randrange(-10**9,10**9+1);lines.append(f'1 {x}');answers.append(min(a*x+b for a,b in points))
 data=('\n'.join(lines)+'\n').encode();out=subprocess.check_output([str(p/'reference')],input=data);expected=('\n'.join(map(str,answers))+'\n').encode();assert out==expected;checks+=len(answers);records.append({'input_sha256':hashlib.sha256(data).hexdigest(),'output_sha256':hashlib.sha256(out).hexdigest()})
(p/'reference_selfcheck.json').write_text(json.dumps({'seed':915873,'cases':48,'exact_python_integer_checks':checks,'cases_sha256':records},indent=2)+'\n');print('reference checked',checks,'exact answers')

