#include SIRKIT_LC1D_SOURCE
#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <string>
#include <vector>
using I=std::int64_t;
struct Summary {I value=0,k=0,m=0;};
static std::uint64_t checks=0;
static void require(bool ok){++checks;if(!ok)std::abort();}
static void barrier(){std::atomic_signal_fence(std::memory_order_seq_cst);}
template<Objective O>void prepare(const std::string& shape,LineContainer<I,O>& lines,std::vector<I>& xs){
 std::mt19937_64 rng(814732);
 const int n=shape=="one"?1:shape=="small"?32:8193;
 for(int i=0;i<n;++i){
  I k{},m{};
  if(shape=="parabola"){k=i-4096;m=O==MINIMIZE?k*k:-k*k;}
  else{k=I(rng()%2001)-1000;m=I(rng()%2000001)-1000000;}
  lines.add(k,m);
 }
 xs.resize(250000);for(auto& x:xs)x=I(rng()%20001)-10000;
}
template<Objective O>void inspect(const LineContainer<I,O>& lines,const std::vector<I>& xs){
 for(const I x:xs){
  const auto result=lines.query_with_line(x);const auto old=lines.query_line(x);
  require(result.value==lines.query(x));require(result.k==old.first&&result.m==old.second);
  require(result.value==result.k*x+result.m);
 }
}
template<bool Fused,Objective O>[[gnu::noinline]]Summary run(const LineContainer<I,O>& lines,const std::vector<I>& xs){
 Summary s;barrier();for(const I x:xs){
  if constexpr(Fused){const auto r=lines.query_with_line(x);s.value+=r.value;s.k+=r.k;s.m+=r.m;}
  else{const I v=lines.query(x);const auto [k,m]=lines.query_line(x);s.value+=v;s.k+=k;s.m+=m;}
 }barrier();return s;
}
template<bool Fused,Objective O>void measure(const char* shape,const LineContainer<I,O>& lines,const std::vector<I>& xs){
 const auto begin=std::chrono::steady_clock::now();const auto s=run<Fused>(lines,xs);
 const double ns=std::chrono::duration<double,std::nano>(std::chrono::steady_clock::now()-begin).count()/xs.size();
 std::printf("%s:%s %.9f %jd,%jd,%jd\n",shape,O==MINIMIZE?"min":"max",ns,static_cast<std::intmax_t>(s.value),static_cast<std::intmax_t>(s.k),static_cast<std::intmax_t>(s.m));
}
template<Objective O>void process(const std::string& mode){
 for(const auto* shape:{"one","small","parabola"}){
  LineContainer<I,O> lines;std::vector<I> xs;prepare(shape,lines,xs);
  if(mode=="check"){inspect(lines,xs);std::printf("checked %s %s hull=%zu\n",shape,O==MINIMIZE?"min":"max",lines.size());}
  else if(mode=="fused")measure<true>(shape,lines,xs);else measure<false>(shape,lines,xs);
 }
}
int main(int argc,char** argv){const std::string mode=argc>1?argv[1]:"check";process<MINIMIZE>(mode);process<MAXIMIZE>(mode);if(mode=="check")std::printf("PASS %ju checks\n",static_cast<std::uintmax_t>(checks));}

