#endif
        return fast;
''';q=b.replace(s,'');assert q!=b;(p/'wide.hpp').write_text(q)
start='''    auto z = insert({k, m, 0}), y = z++, x = y;'''
replace='''    auto z = lower_bound(Line<T>{k, m, 0});
    if (z != end() && z->k == k) {
      const bool better = objective == MAXIMIZE ? m > z->m : m < z->m;
      if (!better) return;
