#include SIRKIT_LC1D_SOURCE
#include <boost/multiprecision/cpp_int.hpp>
#include <random>
#include <vector>
#include <iostream>
#include <cstdlib>
using Big=boost::multiprecision::cpp_int;
static std::uint64_t checks=0;
static void req(bool b){++checks;if(!b)std::abort();}
template<class T,Objective Obj>static void test(){
 std::mt19937_64 rng(833912);constexpr T low=std::numeric_limits<T>::min(),high=std::numeric_limits<T>::max();
 for(int series=0;series<120;++series){
  LineContainer<T,Obj> h;std::vector<std::pair<T,T>> all;
  for(int i=0;i<70;++i){
   T k=static_cast<T>(rng()),m=static_cast<T>(rng());
   if(series%4==0){k=static_cast<T>(rng()%11-5);m=static_cast<T>(rng()%41-20);}
   if(i%11==0)k=i%2?low:high;
   if(i%13==0)m=i%2?low:high;
   if(i%7==0&&!all.empty())k=all.back().first;
   h.add(k,m);all.emplace_back(k,m);
   for(int j=0;j<12;++j){T x=j==0?low:j==1?high:j==2?T{0}:j==3?T{1}:j==4?T{-1}:static_cast<T>(rng());Big best;bool first=true;
    for(auto[a,b]:all){Big v=Big(a)*x+b;if(first||(Obj==MINIMIZE?v<best:v>best)){best=v;first=false;}}
    bool over=best<Big(low)||best>Big(high),caught=false;T got{};try{got=h.query(x);}catch(const std::overflow_error&){caught=true;}req(caught==over);if(!over)req(Big(got)==best);
    auto[a,b]=h.query_line(x);req(Big(a)*x+b==best);
   }
  }
 }
}
template<Objective Obj>static void floating(){std::mt19937_64 rng(819237);for(int s=0;s<60;++s){LineContainer<long double,Obj>h;std::vector<std::pair<long double,long double>>a;for(int i=0;i<60;++i){long double k=(std::int64_t(rng()%81)-40)/4.L,m=(std::int64_t(rng()%81)-40)/8.L;h.add(k,m);a.emplace_back(k,m);for(int j=0;j<10;++j){long double x=(std::int64_t(rng()%801)-400)/4.L,best=Obj==MINIMIZE?std::numeric_limits<long double>::infinity():-std::numeric_limits<long double>::infinity();for(auto[k,m]:a){auto v=k*x+m;best=Obj==MINIMIZE?std::min(best,v):std::max(best,v);}req(h.query(x)==best);auto[k,m]=h.query_line(x);req(k*x+m==best);}}}}
int main(){test<std::int8_t,MINIMIZE>();test<std::int8_t,MAXIMIZE>();test<std::int16_t,MINIMIZE>();test<std::int16_t,MAXIMIZE>();test<std::int32_t,MINIMIZE>();test<std::int32_t,MAXIMIZE>();test<std::int64_t,MINIMIZE>();test<std::int64_t,MAXIMIZE>();floating<MINIMIZE>();floating<MAXIMIZE>();std::cout<<"PASS "<<checks<<" cpp_int/dyadic checks\n";}

