#include SIRKIT_LC1D_SOURCE
#include <boost/multiprecision/cpp_int.hpp>
#include <vector>
#include <iostream>
#include <random>
#include <cstdlib>
using Big=boost::multiprecision::cpp_int;
static std::uint64_t checks=0;
static void req(bool b){++checks;if(!b)std::abort();}
template<class T,Objective Obj>static void inspect(const LineContainer<T,Obj>&h,const std::vector<std::pair<T,T>>&all,T x){Big best;bool first=true;for(auto[k,m]:all){Big v=Big(k)*x+m;if(first||(Obj==MINIMIZE?v<best:v>best)){best=v;first=false;}}bool overflow=best<Big(std::numeric_limits<T>::min())||best>Big(std::numeric_limits<T>::max()),caught=false;T got{};try{got=h.query(x);}catch(const std::overflow_error&){caught=true;}req(caught==overflow);if(!overflow)req(Big(got)==best);auto[k,m]=h.query_line(x);req(Big(k)*x+m==best);}
template<class T,Objective Obj>static void run(){
 constexpr T lo=std::numeric_limits<T>::min(),hi=std::numeric_limits<T>::max();
 const int n=sizeof(T)==2?150:400;LineContainer<T,Obj>h;std::vector<std::pair<T,T>>all;
 const auto add=[&](T k,T m){h.add(k,m);all.emplace_back(k,m);for(T x:{lo,hi,T{0},T{-1},T{1}})inspect(h,all,x);};
 for(int k=-n;k<=n;++k)add(static_cast<T>(k),static_cast<T>(Obj==MINIMIZE?k*k:-k*k));
 req(h.size()==static_cast<std::size_t>(2*n+1));
 for(int x=-2*n-5;x<=2*n+5;++x)inspect(h,all,static_cast<T>(x));
 // 大きい包絡から3本へ戻し、小さい包絡の挿入へ再び入る。
 add(0,Obj==MINIMIZE?lo:hi);req(h.size()<=5);
 for(int j=0;j<80;++j){T k=static_cast<T>(j%11-5),m=Obj==MINIMIZE?static_cast<T>(lo+1+j):static_cast<T>(hi-1-j);add(k,m);inspect(h,all,static_cast<T>(j*7-200));}
