#include <algorithm>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <iterator>
#include <limits>
#include <optional>
#include <set>
#include <stdexcept>
#include <type_traits>
#include <utility>

#ifndef SIRKIT_LINE_CONTAINER_DEFINED
#define SIRKIT_LINE_CONTAINER_DEFINED

enum Objective { MAXIMIZE = +1, MINIMIZE = -1 };

// k,m: 元の係数。p: この直線が選ばれる右端(整数は型の範囲に制限)。
template <typename T>
struct Line {
  mutable T k, m, p;
  bool operator<(const Line& other) const { return k < other.k; }
  bool operator<(T x) const { return p < x; }
