      else if (!std::isfinite(n) && !std::isfinite(d))
        a.p = (b.m / 2 - a.m / 2) / (a.k / 2 - b.k / 2);
      else if (!std::isfinite(n)) a.p = ((b.m / 2 - a.m / 2) / d) * 2;
      else a.p = (n / (a.k / 2 - b.k / 2)) / 2;
