        return k * x + m;
      const U a = k < 0 ? U{0} - U(k) : U(k);
      const U b = x < 0 ? U{0} - U(x) : U(x);
      const U c = m < 0 ? U{0} - U(m) : U(m);
      constexpr U mask = 0xffffffffU;
