  static bool boundary_less(const Line<T>& a, const Line<T>& b) {
    return a.p < b.p;
  }
  static bool intersection(Line<T> const& a, Line<T> const& b) {
    if constexpr (std::is_integral_v<T>) {
      using U = std::make_unsigned_t<T>;
