      if constexpr (std::is_integral_v<T>) {
        x->p = better ? inf : std::numeric_limits<T>::min();
        below = !better;
      }
      else x->p = better ? inf : -inf;
    } else below = intersection(*x, *y);
    return !below && !boundary_less(*x, *y);
  }

