  friend struct LineContainer2D;
  void add_unchecked(T k, T m) {
    auto z = lower_bound(Line<T>{k, m, 0});
    if (z != end() && z->k == k) {
      const bool better = objective == MAXIMIZE ? m > z->m : m < z->m;
      if (!better) return;
