      Line<T> candidate{k, m, inf};
      if (z != end() && intersection(candidate, *z)) return;
      if (z != begin()) {
        Line<T> previous = *std::prev(z);
        const bool previous_below = intersection(previous, candidate);
        if (!previous_below && previous.p >= candidate.p &&
            (z == end() || candidate.p < z->p)) return;
      }
    }
    auto y = insert(z, {k, m, 0}), x = y;
    z = std::next(y);
