#if defined(__GNUC__) || defined(__clang__)
  __attribute__((always_inline))
#endif
  T query(T x) const {
    if constexpr (std::is_integral_v<T>) {
#ifndef SKIP_RUNTIME_CHECKS
      if (empty()) throw std::out_of_range("LineContainer: empty query");
#endif
