  __attribute__((always_inline))
#endif
  static T evaluate(T k, T m, T x) {
    if constexpr (std::is_floating_point_v<T>) return k * x + m;
    else if constexpr (sizeof(T) < 8) {
      const std::int64_t result = std::int64_t(k) * x + m;
