  }
  void add(T k, T m) {
#ifndef SKIP_RUNTIME_CHECKS
    if constexpr (std::is_floating_point_v<T>)
      if (!std::isfinite(k) || !std::isfinite(m))
        throw std::invalid_argument("LineContainer: nonfinite coefficient");
#endif
    add_unchecked(k, m);
  }

 private:
  friend struct LineContainer2D;
